// src/app/components/game-components/arrow-component/Arrow.ts
var Arrow = class {
  start;
  landing;
  dir;
  getCenterAt;
  transformation;
  startCenter;
  landingCenter;
  constructor(start, landing, dir, getCenterAt) {
    this.start = start;
    this.landing = landing;
    this.dir = dir;
    this.getCenterAt = getCenterAt;
    const pointedCenter = this.getCenterAt(landing);
    const centerCoord = pointedCenter.x + " " + pointedCenter.y;
    const angle = dir.getAngle() + 150;
    const rotation = "rotate(" + angle + " " + centerCoord + ")";
    const translation = "translate(" + centerCoord + ")";
    this.transformation = rotation + " " + translation;
    this.startCenter = this.getCenterAt(this.start);
    this.landingCenter = this.getCenterAt(this.landing);
  }
};

// src/app/components/BaseComponent.ts
var BaseComponent = class {
  // Make some utilities available in all components
  ArrayUtils = ArrayUtils;
  MGPOptional = MGPOptional;
  /**
   * Gets the CSS class for a player color
   */
  getPlayerClass(player, suffix = "fill") {
    switch (player) {
      case Player.ZERO:
        return "player0-" + suffix;
      case Player.ONE:
        return "player1-" + suffix;
      default:
        Utils.expectToBe(player, PlayerOrNone.NONE);
        return "";
    }
  }
};

