var TriangularGameComponent = class extends GameComponent {
  constructor(urlName) {
    super(urlName);
  }
  SPACE_SIZE = 100;
  board;
  getTriangleCornerCoordsAtXY(x2, y) {
    if ((x2 + y) % 2 === 0) {
      return this.getUpwardCoordinate();
    } else {
      return this.getDownwardCoordinate();
    }
  }
  getTrianglePointsAt(coord) {
    return this.getTrianglePointsAtXY(coord.x, coord.y);
  }
  getTrianglePointsAtXY(x2, y) {
    const coords = this.getTriangleCornerCoordsAtXY(x2, y);
    return this.mapCoordsToPoints(coords);
  }
  getTriangleTranslationCoord(coord) {
    const translationX = 0.5 * coord.x * this.SPACE_SIZE;
    const translationY = coord.y * this.SPACE_SIZE;
    return new Coord(translationX, translationY);
  }
  getTriangleTranslationAt(coord) {
    return this.getTriangleTranslationAtXY(coord.x, coord.y);
  }
  getTriangleTranslationAtXY(x2, y) {
    const coord = new Coord(x2, y);
    const translation = this.getTriangleTranslationCoord(coord);
    return this.getSVGTranslationAt(translation);
  }
  getDownwardCoordinate() {
    const left = 0;
    const middle = this.SPACE_SIZE / 2;
    const right = this.SPACE_SIZE;
    const top = 0;
    const bottom = this.SPACE_SIZE;
    const leftCorner = new Coord(left, top);
    const middleCorner = new Coord(middle, bottom);
    const rightCorner = new Coord(right, top);
    return [leftCorner, middleCorner, rightCorner, leftCorner];
  }
  getUpwardCoordinate() {
    const left = 0;
    const middle = this.SPACE_SIZE / 2;
    const right = this.SPACE_SIZE;
    const top = 0;
    const bottom = this.SPACE_SIZE;
    const leftCorner = new Coord(left, bottom);
    const middleCorner = new Coord(middle, top);
    const rightCorner = new Coord(right, bottom);
    return [leftCorner, middleCorner, rightCorner, leftCorner];
  }
  getPyramidPointsAt(coord) {
    return this.getPyramidPointsAtXY(coord.x, coord.y);
  }
  getPyramidPointsAtXY(x2, y) {
    if ((x2 + y) % 2 === 1) {
      return this.getDownwardPyramidPoints();
    } else {
      return this.getUpwardPyramidPoints();
    }
  }
  getDownwardPyramidCoords() {
    const width = this.SPACE_SIZE;
    const halfWidth = this.SPACE_SIZE / 2;
    const UP_LEFT = new Coord(0, 0);
    const UP_RIGHT = new Coord(width, 0);
    const DOWN_CENTER = new Coord(halfWidth, width);
    const CENTER = new Coord(halfWidth, halfWidth);
    return [
      UP_LEFT,
      DOWN_CENTER,
      CENTER,
      UP_LEFT,
      CENTER,
      UP_RIGHT,
      UP_LEFT,
      UP_RIGHT,
      DOWN_CENTER,
      CENTER,
      UP_RIGHT
    ];
  }
  getDownwardPyramidPoints() {
    const coords = this.getDownwardPyramidCoords();
    return this.mapCoordsToPoints(coords);
  }
  mapCoordsToPoints(coords) {
    return coords.map((coord) => coord.toSVGPoint()).join(", ");
  }
  getUpwardPyramidCoords() {
    const halfWidth = this.SPACE_SIZE / 2;
    const width = this.SPACE_SIZE;
    const DOWN_LEFT = new Coord(0, width);
    const DOWN_RIGHT = new Coord(width, width);
    const UP_CENTER = new Coord(halfWidth, 0);
    const CENTER = new Coord(halfWidth, halfWidth);
    return [
      DOWN_LEFT,
      UP_CENTER,
      CENTER,
      DOWN_LEFT,
      CENTER,
      DOWN_RIGHT,
      DOWN_LEFT,
      DOWN_RIGHT,
      UP_CENTER,
      CENTER,
      DOWN_RIGHT
    ];
  }
  getUpwardPyramidPoints() {
    const coords = this.getUpwardPyramidCoords();
    return this.mapCoordsToPoints(coords);
  }
};

